@custom-variant dark (&:is(.dark *));

/* ---------------------------------------------------------------------------
   Brand tokens, from DESIGN.md.
   These are what `bg-canvas`, `text-ink`, `border-hairline` and the timeline
   pastels compile to. Without them every one of those classes in app/page.tsx
   is a no-op and the page falls through to the bare shadcn palette.
   --------------------------------------------------------------------------- */
@theme {
    --color-canvas: #f7f7f4;
    --color-canvas-soft: #fafaf7;
    --color-surface-card: #ffffff;
    --color-surface-strong: #e6e5e0;

