/**
 * Seeded Incident fixtures.
 *
 * Imported statically instead of read with `fs` so the JSON is bundled with the
 * route handler on Vercel.
 */

import caseOne from "@/lib/cases/fixtures/CASE-001.json"
import type { Incident } from "./types"

const FIXTURES: Record<string, Incident> = {
  "CASE-001": caseOne,
}

export function incidentFixture(caseId: string): Incident | undefined {
  return FIXTURES[caseId]
}

const MONEY = /^-?\d+(\.\d+)?$/

/** Returns the problem with `value` as an Incident, or null when it is one. */
export function incidentProblem(value: unknown): string | null {
  if (typeof value !== "object" || value === null)
    return "incident must be an object"
  const it = value as Record<string, unknown>
  for (const key of ["case_id", "part_id", "line_stop_at", "currency"]) {
    if (typeof it[key] !== "string" || it[key] === "") {
      return `incident.${key} must be a non-empty string`
    }
  }
  for (const key of ["qty_required", "qty_on_hand"]) {
    if (!Number.isInteger(it[key])) return `incident.${key} must be an integer`
  }
  for (const key of ["line_stop_cost_per_hour", "expedite_fee"]) {
    if (typeof it[key] !== "string" || !MONEY.test(it[key] as string)) {
      return `incident.${key} must be a decimal string, not a float`
    }
  }
  return null
}
/**
 * In-memory case + event store.
 *
 * Vercel serverless has no durable local disk, so Slice 1 keeps everything in
 * a module-level map keyed by case_id. It survives only for the lifetime of a
 * single serverless instance: a case created by one instance is invisible to
 * another and disappears on cold start. That is accepted for this slice — a
 * durable store (KV/Turso) is a later slice, not this one.
 */

import type { CaseEvent, CaseRecord, EventLevel, Incident } from "./types"

type CaseState = {
  record: CaseRecord
  events: CaseEvent[]
}

const cases = new Map<string, CaseState>()

export function createCase(incident: Incident): CaseRecord {
  const record: CaseRecord = {
    case_id: incident.case_id,
    incident,
    created_at: new Date().toISOString(),
    session_id: null,
    session_url: null,
  }
  // Re-running the CLI on the same case_id restarts the case rather than
  // interleaving two runs in one event log.
  cases.set(record.case_id, { record, events: [] })
  return record
}

export function getCase(caseId: string): CaseRecord | undefined {
  return cases.get(caseId)?.record
}

export function setSession(
  caseId: string,
  sessionId: string | null,
  sessionUrl: string | null
): void {
  const state = cases.get(caseId)
  if (!state) return
  state.record.session_id = sessionId
  state.record.session_url = sessionUrl
}

export function appendEvent(
  caseId: string,
  event: {
    actor: string
    stage: string
    message: string
    level?: EventLevel
    payload?: Record<string, unknown>
  }
): CaseEvent {
  const stored: CaseEvent = {
    case_id: caseId,
    ts: new Date().toISOString(),
    actor: event.actor,
    stage: event.stage,
    level: event.level ?? "info",
    message: event.message,
    payload: event.payload ?? {},
  }
  const state = cases.get(caseId)
  if (state) state.events.push(stored)
  return stored
}

export function eventsFor(caseId: string): CaseEvent[] {
  return [...(cases.get(caseId)?.events ?? [])]
}

/** Test helper. Never called from a route handler. */
export function resetStore(): void {
  cases.clear()
}
/**
 * Devin session launcher.
 *
 * Real path: POST {DEVIN_API_BASE_URL}/v1/sessions with a bearer token
 * (https://docs.devin.ai/api-reference/v1/sessions/create-a-new-devin-session).
 * Without DEVIN_API_KEY we return a stub session so Slice 1 never fails on a
 * missing key. The key is only ever read from the environment.
 */

import type { Incident } from "./types"
import { shortfall } from "./types"

const DEFAULT_API_BASE_URL = "https://api.devin.ai"

export type DevinSession = {
  session_id: string
  session_url: string
  stubbed: boolean
  /** Set when the real API was attempted and failed; we still return a stub. */
  error?: string
}

export function backendBaseUrl(requestUrl: string): string {
  const configured = process.env.DEVIN_BACKEND_BASE_URL
  if (configured) return configured.replace(/\/$/, "")
  if (process.env.VERCEL_URL) return `https://${process.env.VERCEL_URL}`
  return new URL(requestUrl).origin
}

export function sessionPrompt(incident: Incident, baseUrl: string): string {
  return [
    `You are launching sourcing case ${incident.case_id}. Do not wait for a human — there is nobody to ask.`,
    `Backend base URL: ${baseUrl}. Read the case with GET ${baseUrl}/api/cases/${incident.case_id}/events.`,
    `Part ${incident.part_id} is short by ${shortfall(incident)} units (required ${incident.qty_required}, on hand ${incident.qty_on_hand}).`,
    `The line stops at ${incident.line_stop_at}. Costs are ${incident.currency} ${incident.line_stop_cost_per_hour}/hour of line stop and ${incident.expedite_fee} expedite fee.`,
    `Call only this backend. Do not place phone calls and do not contact suppliers in this slice.`,
  ].join("\n")
}

function stubSession(incident: Incident, error?: string): DevinSession {
  const suffix = incident.case_id.toLowerCase().replace(/[^a-z0-9]+/g, "-")
  const sessionId = `devin-stub-${suffix}-${Date.now()}`
  return {
    session_id: sessionId,
    session_url: `https://app.devin.ai/sessions/${sessionId}`,
    stubbed: true,
    error,
  }
}

export async function startDevinSession(
  incident: Incident,
  baseUrl: string
): Promise<DevinSession> {
  const apiKey = process.env.DEVIN_API_KEY
  if (!apiKey) return stubSession(incident)

  const apiBase = (
    process.env.DEVIN_API_BASE_URL ?? DEFAULT_API_BASE_URL
  ).replace(/\/$/, "")

  try {
    const response = await fetch(`${apiBase}/v1/sessions`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${apiKey}`,
      },
      body: JSON.stringify({
        prompt: sessionPrompt(incident, baseUrl),
        title: `Sourcing ${incident.case_id} (${incident.part_id})`,
        tags: ["supplyguard", incident.case_id],
      }),
    })
    if (!response.ok) {
      const body = await response.text()
      return stubSession(
        incident,
        `Devin API ${response.status}: ${body.slice(0, 200)}`
      )
    }
    const data = (await response.json()) as {
      session_id?: string
      url?: string
    }
    if (!data.session_id) {
      return stubSession(incident, "Devin API response had no session_id")
    }
    return {
      session_id: data.session_id,
      session_url:
        data.url ?? `https://app.devin.ai/sessions/${data.session_id}`,
      stubbed: false,
    }
  } catch (error) {
    return stubSession(incident, `Devin API request failed: ${String(error)}`)
  }
}

